const interruptStartupSteps = `-- name: InterruptStartupSteps :one
WITH candidates AS MATERIALIZED (
 SELECT s.id FROM steps s JOIN runs parent ON parent.id=s.run_id
 WHERE s.status=$1 AND NOT (s.id=ANY($2::uuid[])) AND NOT (s.type='workflow/call' AND EXISTS (
  SELECT 1 FROM runs child WHERE child.parent_step_id=s.id
   AND child.parent_run_id=s.run_id AND child.parent_step_attempt=s.attempt
   AND child.project_id=parent.project_id
   AND child.id::text=s.evidence_json->>'childRunId' AND child.status=$3))
 ORDER BY s.id FOR UPDATE OF s
), changed AS (
 UPDATE steps SET status=$4,finished_at=$5::timestamptz,
  evidence_json=CASE WHEN steps.type = ANY($6::text[]) THEN $7::jsonb ELSE '{"reason":"orphaned by apptownd restart"}'::jsonb END
 FROM candidates WHERE steps.id=candidates.id AND steps.status=$1 RETURNING steps.id
) SELECT (SELECT count(*) FROM candidates) AS expected,(SELECT count(*) FROM changed) AS interrupted
`

type InterruptStartupStepsParams struct {
	RunningStatus  string
	PreservedSteps []ids.ID
	ChildStatus    string
	NextStatus     string
	At             time.Time
	EndedTypes     []string
	EndedEvidence  json.RawMessage
}

type InterruptStartupStepsRow struct {
	Expected    int64
	Interrupted int64
}

func (q *Queries) InterruptStartupSteps(ctx context.Context, arg InterruptStartupStepsParams) (InterruptStartupStepsRow, error) {
	row := q.db.QueryRowContext(ctx, interruptStartupSteps,
		arg.RunningStatus,
		pq.Array(arg.PreservedSteps),
		arg.ChildStatus,
		arg.NextStatus,
		arg.At,
		pq.Array(arg.EndedTypes),
		arg.EndedEvidence,
	)
	var i InterruptStartupStepsRow
	err := row.Scan(&i.Expected, &i.Interrupted)
	return i, err
}

