const landingAcceptanceConsidered = `-- name: LandingAcceptanceConsidered :many
SELECT (payload_json->>'stepId')::uuid AS step_id FROM run_events WHERE run_id=$1 AND kind IN ('landing.acceptance.carried','landing.acceptance.withheld') AND payload_json->>'stepId' IS NOT NULL
`

func (q *Queries) LandingAcceptanceConsidered(ctx context.Context, runID ids.ID) ([]ids.ID, error) {
	rows, err := q.db.QueryContext(ctx, landingAcceptanceConsidered, runID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ids.ID
	for rows.Next() {
		var step_id ids.ID
		if err := rows.Scan(&step_id); err != nil {
			return nil, err
		}
		items = append(items, step_id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

